function Icon({ name, size = 20 }: { name: string; size?: number }) { return <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.65" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">{paths[name] || paths.tasks}</svg>; }
function CalendarNavigator({startDay,selectedDay,today,onSelect,onToday}:{startDay:string;selectedDay:string|null;today:string;onSelect:(day:string)=>void;onToday:()=>void}) {
  const [month,setMonth]=useState(startDay.slice(0,7));
  useEffect(()=>setMonth(startDay.slice(0,7)),[startDay]);
  function moveMonth(offset:number) {
    const date=new Date(`${month}-01T12:00:00Z`);date.setUTCMonth(date.getUTCMonth()+offset);setMonth(date.toISOString().slice(0,7));
  }
  return <aside className="calendar-navigator" aria-label="Calendar navigator">
    <div className="navigator-heading"><h3 aria-live="polite">{new Intl.DateTimeFormat('en-GB',{month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(`${month}-01T12:00:00Z`))}</h3><div><button className="navigator-previous" aria-label="Previous month" onClick={()=>moveMonth(-1)}><Icon name="chevron" size={17}/></button><button className="navigator-next" aria-label="Next month" onClick={()=>moveMonth(1)}><Icon name="chevron" size={17}/></button></div></div>
    <div className="navigator-weekdays" aria-hidden="true">{['S','M','T','W','T','F','S'].map((day,index)=><span key={index}>{day}</span>)}</div>
    <div className="navigator-dates">{monthCalendar(month).map(({day,inMonth,label})=><button key={day} className={`${inMonth?'':'outside-month'} ${day===today?'is-today':''} ${day===(selectedDay||startDay)?'is-selected':''}`} aria-label={new Intl.DateTimeFormat('en-GB',{dateStyle:'full',timeZone:'UTC'}).format(new Date(`${day}T12:00:00Z`))} aria-pressed={day===(selectedDay||startDay)} aria-current={day===today?'date':undefined} onClick={()=>onSelect(day)}>{label}</button>)}</div>
    <button className="navigator-today" onClick={()=>{setMonth(today.slice(0,7));onToday();}}>Today</button>
  </aside>;
}
function Avatar({ name, index = 0 }: { name: string; index?: number }) { return <span className={`avatar tone-${index % 3}`}>{name.split(' ').map(n => n[0]).slice(0, 2).join('')}</span>; }
function ChannelBadge({channel}:{channel:Channel}){return <span className={`channel-badge ${channel}`}><Icon name={channel} size={13}/>{channelLabel(channel)}</span>;}
const clientNumber=(client?:Client)=>client?.phone||(client&&clientChannel(client)==='whatsapp'&&client.chatId.endsWith('@c.us')?'+'+client.chatId.split('@')[0]:'');
async function api(path: string, method = 'GET', body?: unknown) {
  let res:Response;try{res = await fetch(`/api${path}`, { method, headers: { ...(body===undefined?{}:{'Content-Type':'application/json'}), 'X-FollowThrough': 'dashboard' }, body: body === undefined ? undefined : JSON.stringify(body) });}catch{throw new Error('Cannot reach FollowThrough. Keep the app running and try again.');}
  return readApiResponse(res,path);
}
